//! Runtime for binaries generated by djrs.
//!
//! A generated binary is a front door for a Django project: it resolves each
//! request's URL exactly as Django would, answers it with a generated Rust
//! handler when one exists, and otherwise forwards it, unchanged, to Django
//! running on an internal port.

pub mod app;
pub mod config;
pub mod proxy;
pub mod server;
pub mod urls;

pub use app::{App, Dispatcher, Handler, HandlerFuture, NativeRequest, Outcome, State};
pub use config::Config;

/// Entry point used by generated `main.rs`: read config, log, serve until SIGTERM.
pub fn run(app: App) {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_env("DJRS_LOG")
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();
    let config = match Config::from_env() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("djrs: {e}");
            std::process::exit(2);
        }
    };
    for p in app.tree.opaque_patterns() {
        tracing::warn!(pattern = %p, "pattern can't be matched here; requests reaching it go to Django");
    }
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");
    let dispatcher = Dispatcher::new(app, config);
    if let Err(e) = runtime.block_on(server::serve(dispatcher)) {
        eprintln!("djrs: {e}");
        std::process::exit(1);
    }
}
